class Solution:

    def __init__(self, w: List[int]):
        self.prefix = [0]
        for val in w:
            self.prefix.append(val + self.prefix[-1])

    def pickIndex(self) -> int:
        pick = random.randrange(0, self.prefix[-1])

        low, high = 0, len(self.prefix) - 1
        idx = -1
        while low <= high:
            mid = low + (high - low) // 2

            if self.prefix[mid] > pick:
                idx = mid
                high = mid - 1
            else:
                low = mid + 1
        return idx - 1



